const jyotirlingas=[{name:"Somnath Jyotirlinga",file:"somnath.html",location:"Gujarat"},{name:"Mallikarjuna Jyotirlinga",file:"mallikarjuna.html",location:"Andhra Pradesh"},{name:"Mahakaleshwar Jyotirlinga",file:"mahakaleshwar.html",location:"Madhya Pradesh"},{name:"Omkareshwar Jyotirlinga",file:"omkareshwar.html",location:"Madhya Pradesh"},{name:"Kedarnath Jyotirlinga",file:"kedarnath.html",location:"Uttarakhand"},{name:"Bhimashankar Jyotirlinga",file:"bhimashankar.html",location:"Maharashtra"},{name:"Kashi Vishwanath Jyotirlinga",file:"kashi_vishwanath.html",location:"Uttar Pradesh"},{name:"Trimbakeshwar Jyotirlinga",file:"trimbakeshwar.html",location:"Maharashtra"},{name:"Vaidyanath Jyotirlinga",file:"vaidyanath.html",location:"Jharkhand"},{name:"Nageshwar Jyotirlinga",file:"nageshwar.html",location:"Gujarat"},{name:"Rameshwar Jyotirlinga",file:"rameshwar.html",location:"Tamil Nadu"},{name:"Grishneshwar Jyotirlinga",file:"grishneshwar.html",location:"Maharashtra"}];let visitCount=0;function renderCards(){const e=document.getElementById("jyotirlingasGrid");e.innerHTML="",jyotirlingas.forEach(t=>{const n=document.createElement("div");n.className="jyotirlinga-card",n.innerHTML=`\n            <img src="images/${t.file.replace(".html",".jpg")}" alt="${t.name}" class="card-image" loading="lazy">\n            <div class="card-content">\n                <h3 class="card-title">${t.name}</h3>\n                <p class="card-description">Location: ${t.location}</p>\n            </div>\n        `,n.style.cursor="pointer",n.addEventListener("click",()=>{recordVisit(),window.location.href=t.file}),e.appendChild(n)})}function initializeSearch(){const e=document.getElementById("searchInput"),t=document.getElementById("searchDropdown");e&&(e.addEventListener("input",function(n){const o=n.target.value.toLowerCase();0===o.length?t.style.display="none":(function(e){const n=jyotirlingas.filter(t=>t.name.toLowerCase().includes(e));0===n.length?t.style.display="none":(t.innerHTML="",n.forEach(e=>{const n=document.createElement("div");n.className="search-item",n.textContent=e.name,n.addEventListener("click",()=>{recordVisit(),window.location.href=e.file}),t.appendChild(n)}),t.style.display="block")}(o))}),document.addEventListener("click",function(n){n.target!==e&&n.target!==t&&(t.style.display="none")}),e.addEventListener("focus",function(){e.value.length>0&&(t.style.display="block")}))}function initializeVisitCounter(){visitCount=parseInt(localStorage.getItem("visitCount")||0),updateVisitDisplay()}function recordVisit(){visitCount++,localStorage.setItem("visitCount",visitCount),updateVisitDisplay(),console.log("[v0] Visit recorded. Total visits:",visitCount)}function updateVisitDisplay(){const e=document.getElementById("visitCount");e&&(e.textContent=visitCount)}document.addEventListener("DOMContentLoaded",function(){initializeVisitCounter();const e=document.getElementById("jyotirlingasGrid");e&&(renderCards(),initializeSearch())}),window.addEventListener("load",function(){recordVisit(),console.log("[v0] Page loaded. Visit count:",visitCount)}),document.addEventListener("unload",function(){console.log("[v0] Page unloading. Final visit count:",visitCount)});
